# owner: platform
"""Weekly timesheet rows built from a list of shifts."""

from typing import Dict, List
from hourglass.models import Shift
from collections import defaultdict

def _check(shifts: List[Shift]) -> None:
    """Reject an empty list or a blank worker name."""
    if not shifts:
        raise ValueError("no shifts to report")
    for shift in shifts:
        if not shift.worker.strip():
            raise ValueError("blank worker name")

def _tally(shifts: List[Shift]) -> Dict[str, List[int]]:
    """Shift count and minutes for each worker."""
    totals = defaultdict(lambda: [0, 0])
    for shift in shifts:
        totals[shift.worker][0] += 1
        totals[shift.worker][1] += shift.span.minutes
    return totals

def _rank(totals: Dict[str, List[int]]) -> List[str]:
    """Names by minutes worked, then alphabetically."""
    def sort_key(name: str):
        return (-totals[name][1], name)
    return sorted(totals, key=sort_key)

def _line(name: str, count: int, minutes: int) -> str:
    """Like Brisa: 2 shifts, 9.0 hours."""
    word = "shift" if count == 1 else "shifts"
    hours = minutes / 60
    return f"{name}: {count} {word}, {hours:.1f} hours"

# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, busiest first."""
    _check(shifts)
    totals = _tally(shifts)
    ranked = _rank(totals)
    return [_line(name, *totals[name]) for name in ranked]
